"""Machine-level lemmas for n1 (all generated by mexp.py from the specs in evs.py / gen_base.py).
  python gen_machine.py OUT.v   (development file: header + crossings + rule lemmas)"""
import sys, time, pickle
from pathlib import Path
from evs import *
import mexp
from gen_base import RULES as BASE

ORDER = ['H', 'S0', 'P1', 'P2', 'P3', 'P4', 'E']


def gen():
    out = []
    t0 = time.time()
    for name, S, T in BASE:
        tree = mexp.explore(S, T, splits=3)
        g = mexp.Gen(name)
        out += g.lemmas[:0]
        r = mexp.rule_lemma(name, S, T, tree, g, progress=True)
        out += g.lemmas + [r]
    for name in ORDER:
        S, T = EV[name][:2]
        pos = frozenset(EV[name][2]) if len(EV[name]) > 2 else frozenset()
        tree = mexp.explore(S, T, splits=4, positive=pos)
        g = mexp.Gen('X' + name)
        r = mexp.rule_lemma('EV_' + name, S, T, tree, g, progress=False, positive=sorted(pos))
        out += g.lemmas + [r]
    # the halt
    S = EV['HALT'][0]
    tree = mexp.explore(S, None, splits=0)
    assert tree.get('halt') and all(it[0] != 'split' for it in tree['items'])
    g = mexp.Gen('XHALT')
    tac = ['intros.']
    for it in tree['items']:
        tac.append(g.stage(it[2], it[1], it[3]) if it[0] == 'ops' else g.use_loop(it[1]))
    end = tree['end']
    cn, vs = coqgen.free_vars(S, end)
    out += g.lemmas
    out.append('Lemma EV_HALT : forall %s, %s -->* %s.\nProof.\n%s\n  finish_norm.\nQed.\n'
               % (' '.join(cn + vs), coqgen.cfg_coq(S), coqgen.cfg_coq(end), coqgen.wrap(tac)))
    out.append('Lemma EV_HALT_halted : forall %s, halted tm (%s).\nProof. intros. reflexivity. Qed.\n'
               % (' '.join(cn + vs), coqgen.cfg_coq(end)))
    pickle.dump(dict(halt_end=end), open('machine_info.pkl', 'wb'))
    print('generated in %.1fs, %d lemmas' % (time.time() - t0, len(out)), file=sys.stderr)
    return out


def machine_text():
    pl.LEMMAS.clear()
    lem = gen()
    return ('\n(** ** Crossing lemmas (generated) *)\n\n' + coqgen.crossing_lemmas()
            + '\n(** ** Machine-level lemmas (generated by mexp.py) *)\n\n' + '\n'.join(lem))


if __name__ == '__main__':
    text = header('n1 machine part (development)') + '\n' + machine_text()
    Path(sys.argv[1]).write_text(text, newline='\n')
    print('wrote', sys.argv[1], len(text), 'bytes', file=sys.stderr)
